INSERT INTO public.words (word, meaning, category, rarity, classe, origem, curiosidade, pronuncia, exemplo, nivel, sinonimos) VALUES
('escarcéu', 'grande alvoroço, gritaria ou escândalo', 'comportamento', 2, 'substantivo', 'do provençal antigo', 'Quase sempre aparece na expressão "fazer um escarcéu" — alguém reclamando alto demais por pouca coisa.', 'es-car-CÉU', 'A cliente fez o maior escarcéu porque o café veio frio.', 'facil', ARRAY['alvoroço','berreiro','escândalo']),
('baderna', 'desordem, bagunça, tumulto', 'comportamento', 2, 'substantivo', 'de Marietta Baderna, bailarina italiana', 'Vem do nome de uma bailarina que causava furor no Rio de Janeiro em 1851 — os fãs exaltados dela eram os "badernistas".', 'ba-DER-na', 'A reunião virou uma baderna quando o microfone falhou.', 'facil', ARRAY['bagunça','tumulto','desordem']),
('cafuné', 'carinho feito com os dedos na cabeça de alguém', 'sentimento', 2, 'substantivo', 'do quimbundo (língua banta de Angola)', 'Palavra de origem africana sem tradução exata na maioria das línguas — estrangeiros costumam adorar aprendê-la.', 'ca-fu-NÉ', 'A avó fazia cafuné até o neto dormir.', 'facil', ARRAY['carinho','afago']),
('lusco-fusco', 'crepúsculo; hora entre o dia e a noite', 'natureza', 2, 'substantivo', 'formação expressiva do português', 'Nomeia a meia-luz em que já não é dia mas ainda não é noite — horário favorito dos fotógrafos.', 'LUS-co-FUS-co', 'Os morcegos saem no lusco-fusco.', 'facil', ARRAY['crepúsculo','anoitecer']),
('ojeriza', 'antipatia instintiva, aversão', 'sentimento', 2, 'substantivo', 'do espanhol ojeriza', 'No espanhol original tinha a ver com "olhar torto" (ojo = olho) — a antipatia que se vê no olhar.', 'o-je-RI-za', 'Tenho ojeriza a fila de banco.', 'facil', ARRAY['aversão','antipatia','repulsa']),
('muxoxo', 'estalido de língua que demonstra desdém', 'comportamento', 2, 'substantivo', 'onomatopeia', 'A palavra imita o próprio som que descreve — o "tsc" de quem desdenha.', 'mu-XO-xo', 'Ela respondeu com um muxoxo e virou as costas.', 'facil', ARRAY['desdém']),
('fuxico', 'mexerico, fofoca', 'cotidiano', 2, 'substantivo', 'incerta', 'Também nomeia um artesanato nordestino de trouxinhas de tecido costuradas — feito pelas mulheres enquanto... fofocavam.', 'fu-XI-co', 'O fuxico da vizinhança era que ele tinha ganhado na loteria.', 'facil', ARRAY['fofoca','mexerico','boato']),
('pindaíba', 'falta completa de dinheiro', 'regional', 2, 'substantivo', 'do tupi pinda''ýba, "vara de pescar"', 'Estar "na pindaíba" viria da imagem de quem só tem a vara de pescar para conseguir o próprio alimento.', 'pin-da-Í-ba', 'Depois das festas, todo mundo fica na pindaíba.', 'facil', ARRAY['dureza','penúria']),
('mequetrefe', 'pessoa metida, fútil e sem importância', 'pessoa', 2, 'substantivo', 'do espanhol mequetrefe', 'Clássico dos xingamentos antigos de novela — ofende sem precisar de palavrão.', 'me-que-TRE-fe', 'Não vou discutir com esse mequetrefe.', 'facil', ARRAY['joão-ninguém','pelintra']),
('bugiganga', 'objeto de pouco valor ou utilidade', 'objeto', 2, 'substantivo', 'incerta', 'Gaveta de casa brasileira que se preze tem uma coleção oficial de bugigangas.', 'bu-gi-GAN-ga', 'A feira vendia bugigangas de todo tipo.', 'facil', ARRAY['quinquilharia','badulaque']),
('estapafúrdio', 'esquisito, extravagante, absurdo', 'qualidade', 2, 'adjetivo', 'incerta', 'O som da palavra já entrega o significado — é quase impossível dizê-la com seriedade.', 'es-ta-pa-FÚR-dio', 'Apareceu com uma ideia estapafúrdia de vender picolé no inverno.', 'facil', ARRAY['excêntrico','esdrúxulo','absurdo']),
('sorumbático', 'triste, melancólico, sombrio', 'sentimento', 2, 'adjetivo', 'incerta', 'Palavra favorita para descrever segunda-feira de manhã.', 'so-rum-BÁ-ti-co', 'Ficou sorumbático o resto do dia após a derrota.', 'facil', ARRAY['melancólico','taciturno','macambúzio']),
('quiproquó', 'confusão, mal-entendido', 'comportamento', 2, 'substantivo', 'do latim quid pro quo, "isto por aquilo"', 'Era termo das antigas farmácias: trocar um remédio por outro. Virou sinônimo de qualquer troca confusa — e nome de peça de teatro de comédia.', 'qui-pro-QUÓ', 'O quiproquó começou quando as duas reservas caíram no mesmo quarto.', 'medio', ARRAY['imbróglio','mal-entendido','rolo']),
('arrebol', 'vermelhidão do céu ao nascer ou pôr do sol', 'natureza', 2, 'substantivo', 'do espanhol arrebol', 'Palavra querida dos poetas românticos e dos hinos — o Hino do Rio Grande do Sul não tem, mas muita poesia gaúcha sim.', 'ar-re-BOL', 'O arrebol pintou as nuvens de rosa e fogo.', 'medio', ARRAY['crepúsculo']),
('azáfama', 'atividade intensa, pressa, labuta', 'cotidiano', 2, 'substantivo', 'do árabe az-zahma, "aperto, multidão"', 'Muito mais comum em Portugal, onde qualquer véspera de Natal é pura azáfama.', 'a-ZÁ-fa-ma', 'A cozinha do restaurante era só azáfama ao meio-dia.', 'medio', ARRAY['afã','correria','lida']),
('alcunha', 'apelido, geralmente dado por característica', 'pessoa', 2, 'substantivo', 'do árabe al-kunya', 'Nos documentos antigos portugueses, criminosos eram registrados pela alcunha — muitos sobrenomes atuais nasceram assim.', 'al-CU-nha', 'Ganhou a alcunha de Relâmpago por ser o mais lento da turma.', 'medio', ARRAY['apelido','cognome','epíteto']),
('bagatela', 'coisa insignificante, ninharia', 'cotidiano', 2, 'substantivo', 'do italiano bagattella', 'Beethoven chamou de "bagatelas" várias peças curtas de piano — a mais famosa é Für Elise.', 'ba-ga-TE-la', 'Comprou o sofá por uma bagatela no desapego.', 'medio', ARRAY['ninharia','mixaria']),
('cizânia', 'discórdia, desavença semeada entre pessoas', 'comportamento', 2, 'substantivo', 'do grego zizánion, "joio"', 'Vem da parábola bíblica do joio semeado no meio do trigo — daí "semear cizânia".', 'ci-ZÂ-nia', 'O boato só serviu para semear cizânia no grupo.', 'medio', ARRAY['discórdia','desavença']),
('chalaça', 'gracejo, piada, zombaria leve', 'comportamento', 2, 'substantivo', 'incerta', 'No Brasil imperial, "Chalaça" era o apelido do amigo e faz-tudo de Dom Pedro I, famoso pelas piadas e pelos serviços nada oficiais.', 'cha-LA-ça', 'Respondeu à provocação com uma chalaça e desarmou todo mundo.', 'medio', ARRAY['gracejo','pilhéria','troça']),
('comezaina', 'refeição farta e demorada, banquete informal', 'gastronomia', 2, 'substantivo', 'de comer + sufixo -aina', 'O sufixo -aina dá ideia de farra coletiva: comezaina é o almoço de domingo que atravessa a tarde.', 'co-me-ZAI-na', 'O batizado terminou numa comezaina de três horas.', 'medio', ARRAY['banquete','festim','patuscada']),
('basbaque', 'pessoa que fica pasmada com qualquer coisa; tolo', 'pessoa', 2, 'substantivo', 'incerta', 'O basbaque clássico é o personagem que para no meio da calçada olhando prédio alto.', 'bas-BA-que', 'Ficou feito basbaque diante da vitrine.', 'medio', ARRAY['pasmado','paspalhão']),
('bazófia', 'ostentação vazia, gabolice', 'comportamento', 2, 'substantivo', 'do italiano bazzoffia', 'No italiano original era uma sopa rala de restos — em português virou a conversa "encorpada" de quem só tem caldo.', 'ba-ZÓ-fia', 'Aquela história de iate era pura bazófia.', 'medio', ARRAY['gabolice','fanfarronice','prosa']),
('biltre', 'indivíduo desprezível, canalha', 'pessoa', 2, 'substantivo', 'do francês antigo', 'Xingamento fino de romance do século XIX — insulta com elegância de folhetim.', 'BIL-tre', 'O biltre fugiu sem pagar a conta.', 'medio', ARRAY['canalha','patife','velhaco']),
('facécia', 'dito espirituoso, gracejo', 'literatura', 2, 'substantivo', 'do latim facetia', 'No Renascimento, "facécias" eram coletâneas de piadas — best-sellers da época de Gutenberg.', 'fa-CÉ-cia', 'O professor abria toda aula com uma facécia.', 'medio', ARRAY['gracejo','chiste','pilhéria']),
('faniquito', 'ataque nervoso passageiro, chilique', 'comportamento', 2, 'substantivo', 'incerta', 'O faniquito é o primo dramático do chilique: sempre acontece com plateia.', 'fa-ni-QUI-to', 'Teve um faniquito quando viu a nota da prova.', 'medio', ARRAY['chilique','ataque','piti']),
('fuzarca', 'farra barulhenta, festança', 'cotidiano', 2, 'substantivo', 'incerta', 'Palavra dos anos de carnaval antigo — a fuzarca era o bloco que não tinha hora para acabar.', 'fu-ZAR-ca', 'A república fez a maior fuzarca na formatura.', 'medio', ARRAY['farra','pândega','folia']),
('macambúzio', 'triste, cabisbaixo, sorumbático', 'sentimento', 2, 'adjetivo', 'incerta', 'É a cara exata de cachorro que fez arte e sabe que foi descoberto.', 'ma-cam-BÚ-zio', 'Andava macambúzio desde que o time caiu pra segunda divisão.', 'medio', ARRAY['sorumbático','cabisbaixo','tristonho']),
('madraço', 'preguiçoso, vadio', 'pessoa', 2, 'substantivo', 'incerta', 'Em Portugal ainda se diz "madraço" para o aluno que enrola o semestre inteiro.', 'ma-DRA-ço', 'Levanta desse sofá, madraço!', 'medio', ARRAY['preguiçoso','mandrião','vadio']),
('mirabolante', 'espetacular, extraordinário, fantasioso', 'qualidade', 2, 'adjetivo', 'de mirabolano, fruto asiático', 'Vem do nome de um fruto exótico vendido nas boticas antigas — tão exótico que virou sinônimo de exagero.', 'mi-ra-bo-LAN-te', 'Apresentou um plano mirabolante para ficar rico em um mês.', 'medio', ARRAY['fantasioso','extravagante']),
('mixórdia', 'mistura confusa, salada de coisas sem ordem', 'cotidiano', 2, 'substantivo', 'incerta', 'Perfeita para descrever gaveta de cabos: uma mixórdia de fios que ninguém sabe de onde vieram.', 'mi-XÓR-dia', 'O relatório era uma mixórdia de dados sem pé nem cabeça.', 'medio', ARRAY['miscelânea','salsada','confusão']),
('ubíquo', 'que está presente em toda parte ao mesmo tempo', 'ciencia', 2, 'adjetivo', 'do latim ubique, "em todo lugar"', 'Na teologia é atributo de Deus; na tecnologia, do wi-fi — a "computação ubíqua" é a que está em tudo.', 'u-BÍ-quo', 'O celular tornou-se ubíquo na vida moderna.', 'medio', ARRAY['onipresente']),
('inefável', 'que não pode ser expresso em palavras', 'sentimento', 2, 'adjetivo', 'do latim ineffabilis', 'Ironia embutida: é a palavra que existe justamente para dizer o que não se consegue dizer.', 'i-ne-FÁ-vel', 'Sentiu uma alegria inefável ao rever a filha.', 'medio', ARRAY['indizível','indescritível']),
('melífluo', 'doce e suave como o mel (voz, palavras)', 'qualidade', 2, 'adjetivo', 'do latim mel + fluere, "escorrer mel"', 'Descreve a voz de locutor de comercial de margarina — doce a ponto de desconfiar.', 'me-LÍ-fluo', 'Convenceu todo mundo com aquele tom melífluo.', 'medio', ARRAY['suave','adocicado','doce']),
('recôndito', 'escondido, profundo, íntimo', 'lugar', 2, 'adjetivo', 'do latim reconditus', 'Usa-se tanto para lugares (vale recôndito) quanto para segredos ("no mais recôndito da alma").', 're-CÔN-di-to', 'Guardava a lembrança no recôndito da memória.', 'medio', ARRAY['oculto','escondido','ermo']),
('vetusto', 'muito antigo, venerável pela idade', 'historia', 2, 'adjetivo', 'do latim vetustus', 'Não é qualquer coisa velha: vetusto carrega respeito — um casarão vetusto, nunca um chinelo vetusto.', 've-TUS-to', 'O vetusto casarão resistia entre os prédios novos.', 'medio', ARRAY['antigo','secular','ancestral']),
('soçobrar', 'afundar, naufragar; sucumbir', 'nautica', 2, 'verbo', 'do espanhol zozobrar', 'Termo náutico que migrou para a vida: planos, empresas e ânimos também soçobram.', 'so-ço-BRAR', 'O barco soçobrou perto da barra; o projeto, logo depois.', 'medio', ARRAY['naufragar','afundar','sucumbir']),
('taramela', 'peça giratória que tranca portas; tagarela', 'objeto', 2, 'substantivo', 'incerta', '"Dar corda na taramela" é fazer um falador começar a falar — depois não há quem trave a portinha.', 'ta-ra-ME-la', 'A porteira fechava com uma taramela de madeira.', 'medio', ARRAY['tramela','linguarudo']),
('janota', 'pessoa que se veste com elegância exagerada', 'pessoa', 2, 'substantivo', 'incerta', 'Os janotas do século XIX eram os influencers da moda da época: cartola, bengala e muito perfume.', 'ja-NO-ta', 'Chegou todo janota para a festa da firma.', 'medio', ARRAY['almofadinha','dândi','casquilho']),
('chorrilho', 'sequência ininterrupta de coisas', 'cotidiano', 2, 'substantivo', 'do espanhol chorrillo, "jorrinho"', 'Quase sempre vem em pacote ruim: um chorrilho de mentiras, de desaforos, de azares.', 'chor-RI-lho', 'Respondeu com um chorrilho de desculpas esfarrapadas.', 'medio', ARRAY['enxurrada','sucessão','série']),
('rapapé', 'mesura exagerada, bajulação cerimoniosa', 'comportamento', 2, 'substantivo', 'de raspar + pé', 'Vem do gesto literal de raspar o pé no chão ao fazer reverência — quanto mais raspava, mais puxava o saco.', 'ra-pa-PÉ', 'Recebeu o diretor com mil rapapés.', 'medio', ARRAY['salamaleque','mesura','bajulação']),
('imbróglio', 'situação confusa e embaraçosa', 'cotidiano', 2, 'substantivo', 'do italiano imbroglio', 'Palavra que os noticiários adoram: todo escândalo político vira "imbróglio jurídico".', 'im-BRÓ-lio', 'O contrato virou um imbróglio que ninguém resolvia.', 'medio', ARRAY['embrulhada','rolo','trama']),
('interregno', 'intervalo entre dois reinados ou períodos', 'historia', 2, 'substantivo', 'do latim inter + regnum', 'Nasceu para o vazio entre um rei morto e o próximo coroado; hoje serve para qualquer pausa de poder — ou de férias.', 'in-ter-REG-no', 'No interregno entre os dois técnicos, o time jogou melhor.', 'medio', ARRAY['intervalo','hiato','pausa']),
('verossímil', 'que parece verdadeiro, crível', 'literatura', 2, 'adjetivo', 'do latim verisimilis', 'É a alma deste jogo: o blefe vencedor não é o verdadeiro, é o mais verossímil.', 've-ros-SÍ-mil', 'A desculpa era tão verossímil que todos acreditaram.', 'medio', ARRAY['crível','plausível']),
('meandro', 'curva sinuosa de um rio; desvio complicado', 'natureza', 2, 'substantivo', 'do rio Meandro, na atual Turquia', 'O rio Meandro era tão torto que virou nome comum — e "meandros da burocracia" é o rio mais torto de todos.', 'me-AN-dro', 'Perdeu-se nos meandros do processo de visto.', 'medio', ARRAY['sinuosidade','curva','labirinto']),
('quimera', 'fantasia impossível; monstro mitológico', 'literatura', 2, 'substantivo', 'do grego chímaira, "cabra"', 'O monstro tinha corpo de cabra, cabeça de leão e cauda de serpente. Na genética moderna, "quimera" é um organismo com dois DNAs — o monstro virou ciência.', 'qui-ME-ra', 'Viver de música parecia uma quimera, até dar certo.', 'medio', ARRAY['utopia','ilusão','devaneio']),
('petricor', 'cheiro característico de chuva em solo seco', 'ciencia', 2, 'substantivo', 'do grego pétra + ichór', 'Ichór era o "sangue dos deuses" na mitologia — o cheiro de chuva é, literalmente, sangue divino na pedra. O termo foi cunhado por cientistas em 1964.', 'pe-tri-COR', 'O petricor anunciou o temporal antes das nuvens.', 'medio', ARRAY[]::text[]),
('plenilúnio', 'lua cheia', 'natureza', 2, 'substantivo', 'do latim plenus + luna', 'O jeito solene de dizer "lua cheia" — lobisomens de literatura clássica só aparecem no plenilúnio.', 'ple-ni-LÚ-nio', 'O plenilúnio iluminava a estrada sem poste.', 'medio', ARRAY['lua cheia']),
('crisálida', 'estágio da borboleta dentro do casulo', 'animal', 2, 'substantivo', 'do grego chrysallís, de chrysós, "ouro"', 'Algumas crisálidas têm brilho metálico dourado — daí o nome grego vir de "ouro".', 'cri-SÁ-li-da', 'Da crisálida discreta saiu uma borboleta azul.', 'medio', ARRAY['pupa','casulo']),
('serendipidade', 'descoberta valiosa feita por acaso', 'ciencia', 2, 'substantivo', 'do conto persa "Os três príncipes de Serendip"', 'Serendip é o antigo nome do Sri Lanka. A penicilina, o micro-ondas e o post-it nasceram assim: por serendipidade.', 'se-ren-di-pi-DA-de', 'Achou a vaga dos sonhos por pura serendipidade.', 'medio', ARRAY['acaso feliz']),
('borborigmo', 'ronco produzido pelos gases do intestino', 'medicina', 3, 'substantivo', 'do grego borborygmós', 'É o nome técnico do "ronco de barriga" — os médicos auscultam borborigmos para avaliar o intestino.', 'bor-bo-RIG-mo', 'O borborigmo denunciou que ele pulou o almoço.', 'dificil', ARRAY['ronco']),
('epistaxe', 'sangramento pelo nariz', 'medicina', 3, 'substantivo', 'do grego epístaxis, "gotejar sobre"', 'Nome pomposo para o sangramento de nariz de quem tomou uma bolada na aula de educação física.', 'e-pis-TA-xe', 'O ar seco do inverno causou-lhe uma epistaxe.', 'dificil', ARRAY['hemorragia nasal']),
('idiossincrasia', 'característica de comportamento própria de alguém', 'medicina', 3, 'substantivo', 'do grego idiosynkrasía', 'Na medicina antiga era a reação única de cada corpo a remédios; hoje é qualquer mania que só a pessoa tem.', 'i-dios-sin-cra-SI-a', 'Comer pizza com talher é idiossincrasia dele.', 'dificil', ARRAY['peculiaridade','mania']),
('obnubilado', 'encoberto como por nuvens; mente confusa', 'medicina', 3, 'adjetivo', 'do latim ob + nubes, "nuvem"', 'Termo médico real: "consciência obnubilada" descreve o paciente acordado porém fora do ar.', 'ob-nu-bi-LA-do', 'Saiu da anestesia ainda obnubilado.', 'dificil', ARRAY['turvado','confuso']),
('iconoclasta', 'quem destrói imagens ou ataca tradições', 'historia', 3, 'substantivo', 'do grego eikón + klástes, "quebrador de imagens"', 'No Império Bizantino, os iconoclastas literalmente quebravam ícones religiosos. Hoje, basta desafiar qualquer vaca sagrada para ganhar o título.', 'i-co-no-CLAS-ta', 'O crítico iconoclasta detonou o clássico intocável.', 'dificil', ARRAY['rebelde','herege']),
('palimpsesto', 'pergaminho raspado e reutilizado para novo texto', 'literatura', 3, 'substantivo', 'do grego palímpsestos, "raspado de novo"', 'Pergaminho era caro: raspava-se o texto antigo para escrever por cima. Um tratado perdido de Arquimedes foi redescoberto sob as orações de um palimpsesto medieval.', 'pa-limp-SES-to', 'O manuscrito era um palimpsesto com dois séculos de camadas.', 'dificil', ARRAY[]::text[]),
('escaramuça', 'combate breve entre pequenos grupos', 'historia', 3, 'substantivo', 'do italiano scaramuccia', 'Scaramouche, o espadachim fanfarrão da commedia dell''arte (e da música do Queen), tem o nome vindo daí.', 'es-ca-ra-MU-ça', 'Houve escaramuças na fronteira antes da guerra.', 'dificil', ARRAY['refrega','entrevero']),
('pecúlio', 'reserva de dinheiro acumulada com esforço', 'direito', 3, 'substantivo', 'do latim peculium, de pecus, "gado"', 'Na Roma antiga riqueza era gado: pecus deu pecúlio e pecúnia. Era também o que o escravo romano podia poupar para comprar a própria liberdade.', 'pe-CÚ-lio', 'Juntou um pecúlio a vida inteira para abrir a padaria.', 'dificil', ARRAY['poupança','economias']),
('usucapião', 'aquisição de propriedade pelo uso prolongado', 'direito', 3, 'substantivo', 'do latim usucapio, "tomar pelo uso"', 'Instituto jurídico romano vivo até hoje: quem ocupa um imóvel por anos, sem oposição do dono, pode se tornar o dono.', 'u-su-ca-pi-ÃO', 'A família ganhou a casa por usucapião após vinte anos.', 'dificil', ARRAY[]::text[]),
('tergiversar', 'usar evasivas, fugir do assunto', 'direito', 3, 'verbo', 'do latim tergum + versare, "virar as costas"', 'A etimologia é o gesto: quem tergiversa está literalmente dando as costas à pergunta.', 'ter-gi-ver-SAR', 'O deputado tergiversou e não respondeu ao repórter.', 'dificil', ARRAY['evadir-se','esquivar-se']),
('perorar', 'discursar longamente; concluir um discurso', 'direito', 3, 'verbo', 'do latim perorare', 'Na retórica clássica, a peroração era o gran finale do discurso — a parte de arrancar lágrimas do júri.', 'pe-ro-RAR', 'O advogado perorou por uma hora diante do júri.', 'dificil', ARRAY['discursar','arengar']),
('outrossim', 'igualmente, além disso', 'direito', 3, 'advérbio', 'do latim alterum sic', 'Fóssil vivo do português arcaico que sobrevive num único habitat: petições de advogado.', 'ou-tros-SIM', 'Requer, outrossim, a produção de provas.', 'dificil', ARRAY['igualmente','ademais']),
('amiúde', 'com frequência, repetidamente', 'cotidiano', 3, 'advérbio', 'do latim ad minutum', 'Palavra dos clássicos que os concursos públicos adoram cobrar — quem lê Machado a encontra amiúde.', 'a-mi-Ú-de', 'Visitava a avó amiúde, quase toda semana.', 'dificil', ARRAY['frequentemente','seguidamente']),
('assaz', 'bastante, suficientemente', 'literatura', 3, 'advérbio', 'do provençal assatz', 'Sobrevive nos textos solenes e nas piadas de quem quer soar clássico: "estou assaz cansado".', 'as-SAZ', 'A prova revelou-se assaz difícil.', 'dificil', ARRAY['bastante','muito']),
